package rafradek.tf2weapons.weaponclient;

import net.minecraft.client.model.geom.PartPose;
import net.minecraft.client.model.geom.builders.*;
import rafradek.tf2weapons.weapon.projectile.WeaponProjectile;

/** Static geometry migrated from rafradek's ModelRocket/Grenade/Stickybomb/Flare/Syringe (LGPL 2.1).
 * Generated by tools/generate_projectile_geometry.py; historical credits and sources retained.
 */
public final class ProjectileGeometry {
    public static LayerDefinition create(WeaponProjectile.Flight flight) {
        MeshDefinition mesh = new MeshDefinition();
        PartDefinition root = mesh.getRoot();
        switch (flight) {
            case ROCKET -> {
                root.addOrReplaceChild("bigger", CubeListBuilder.create().texOffs(0, 0).mirror().addBox(0F, 0F, 0F, 3F, 2F, 2F), PartPose.offsetAndRotation(-1F, -1F, -1F, 0F, 0F, 0F));
                root.addOrReplaceChild("longer", CubeListBuilder.create().texOffs(0, 4).mirror().addBox(0F, 0F, 0F, 7F, 1F, 1F), PartPose.offsetAndRotation(-4F, -0.5F, -0.5F, 0F, 0F, 0F));
                return LayerDefinition.create(mesh, 32, 32);
            }
            case GRENADE -> {
                root.addOrReplaceChild("Shape1", CubeListBuilder.create().texOffs(0, 0).addBox(0F, 0F, 0F, 4F, 4F, 5F), PartPose.offsetAndRotation(-2F, -2F, -1F, 0F, 0F, 0F));
                root.addOrReplaceChild("Shape2", CubeListBuilder.create().texOffs(0, 9).addBox(0F, 0F, 0F, 3F, 3F, 1F), PartPose.offsetAndRotation(-1.5F, -1.5F, 4F, 0F, 0F, 0F));
                root.addOrReplaceChild("Shape3", CubeListBuilder.create().texOffs(0, 9).addBox(0F, 0F, 0F, 3F, 3F, 1F), PartPose.offsetAndRotation(-1.5F, -1.5F, -2F, 0F, 0F, 0F));
                root.addOrReplaceChild("Shape4", CubeListBuilder.create().texOffs(18, 0).addBox(0F, 0F, 0F, 4F, 4F, 1F), PartPose.offsetAndRotation(-2F, -2F, -3F, 0F, 0F, 0F));
                return LayerDefinition.create(mesh, 32, 32);
            }
            case STICKY -> {
                root.addOrReplaceChild("Shape1", CubeListBuilder.create().texOffs(0, 6).mirror().addBox(0F, 0F, 0F, 3F, 3F, 5F), PartPose.offsetAndRotation(-1F, -1F, -2F, 0F, 0F, 0F));
                root.addOrReplaceChild("Shape2", CubeListBuilder.create().texOffs(0, 14).mirror().addBox(0F, 0F, 0F, 3F, 5F, 3F), PartPose.offsetAndRotation(-1F, -2F, -1F, 0F, 0F, 0F));
                root.addOrReplaceChild("Shape3", CubeListBuilder.create().texOffs(0, 0).mirror().addBox(0F, 0F, 0F, 5F, 3F, 3F), PartPose.offsetAndRotation(-2F, -1F, -1F, 0F, 0F, 0F));
                return LayerDefinition.create(mesh, 16, 32);
            }
            case FLARE -> {
                root.addOrReplaceChild("shape1", CubeListBuilder.create().texOffs(0, 0).addBox(0.0F, 0.0F, 0.0F, 5F, 2F, 2F), PartPose.offsetAndRotation(-2.5F, -1.0F, -1.0F, 0F, 0F, 0F));
                return LayerDefinition.create(mesh, 16, 16);
            }
            case SYRINGE -> {
                root.addOrReplaceChild("Shape1", CubeListBuilder.create().texOffs(0, 6).mirror().addBox(0F, 0F, 1F, 1F, 1F, 5F), PartPose.offsetAndRotation(0F, 0F, 0F, 0F, 0F, 0F));
                root.addOrReplaceChild("Shape2", CubeListBuilder.create().texOffs(0, 0).mirror().addBox(-1F, -1F, 0F, 3F, 3F, 1F), PartPose.offsetAndRotation(0F, 0F, 0F, 0F, 0F, 0F));
                root.addOrReplaceChild("Shape3", CubeListBuilder.create().texOffs(8, 0).mirror().addBox(-0.5F, -0.5F, -3F, 2F, 2F, 3F), PartPose.offsetAndRotation(0F, 0F, 0F, 0F, 0F, 0F));
                root.addOrReplaceChild("Shape4", CubeListBuilder.create().texOffs(0, 0).mirror().addBox(-1F, -1F, -4F, 3F, 3F, 1F), PartPose.offsetAndRotation(0F, 0F, 0F, 0F, 0F, 0F));
                return LayerDefinition.create(mesh, 32, 32);
            }
            case ARROW -> {
                root.addOrReplaceChild("shaft", CubeListBuilder.create().texOffs(0, 0).addBox(-6, -0.25F, -0.25F, 12, 0.5F, 0.5F), PartPose.ZERO);
                return LayerDefinition.create(mesh, 32, 32);
            }
            case ENERGY -> {
                root.addOrReplaceChild("beam", CubeListBuilder.create().texOffs(0, 0).addBox(-6, -0.5F, -0.5F, 12, 1, 1), PartPose.ZERO);
                return LayerDefinition.create(mesh, 16, 16);
            }
        }
        throw new IllegalArgumentException("Unknown projectile flight " + flight);
    }
}
